/** Exact constant probes must retain rows and variable bindings without an adjacency index. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
@Isolated("The raw dispatch fixture controls compilation properties for all execution routes")
class LmdbNativeRawEqualityDispatchTest {

	private static final String NS = "urn:feature-flags:";
	private static final String NATIVE_PROPERTY = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private final Map<String, String> previousProperties = new HashMap<>();

	@BeforeEach
	void enableNativeEngine() {
		setProperty(NATIVE_PROPERTY, "true");
		setProperty("rdf4j.lmdb.janinoCodegen.synchronous", "true");
		setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
	}

	private void setProperty(String property, String value) {
		previousProperties.put(property, System.setProperty(property, value));
	}

	@AfterEach
	void restoreNativeEngine() {
		for (Map.Entry<String, String> entry : previousProperties.entrySet()) {
			if (entry.getValue() == null) {
				System.clearProperty(entry.getKey());
			} else {
				System.setProperty(entry.getKey(), entry.getValue());
			}
		}
		previousProperties.clear();
	}

	@ParameterizedTest(name = "rows={0}, aggregates={1}")
	@CsvSource({
			"automatic,automatic",
			"nestedLoop,nestedLoop",
			"irKernelInterpreted,irAggregateInterpreted",
			"irKernel,irAggregate" })
	void equalityProbePreservesRowsAndCountAcrossRawExecutionRoutes(String rowStrategy, String aggregateStrategy,
			@TempDir Path tempDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		SailRepository repository = new SailRepository(new LmdbStore(tempDir.toFile(), config));
		repository.init();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			addDataset(connection);
			List<String> mismatches = new ArrayList<>();
			for (String body : List.of(
					"?person a :Person . ?person :nick \"Alice\"",
					"?person a :Person . ?person :nick ?nick FILTER(?nick = \"Alice\")",
					"?person a :Person . ?person :nick ?nick FILTER(\"Alice\" = ?nick)",
					"?person a :Person . OPTIONAL { ?person :nick ?nick } FILTER(?nick = \"Alice\")",
					"?person a :Person . OPTIONAL { ?person :nick ?nick } FILTER(\"Alice\" = ?nick)",
					"?person a :Person . GRAPH :graph-one { ?person :member ?member } FILTER(?member = :red)",
					"?person a :Person . OPTIONAL { GRAPH :graph-one { ?person :member ?member } }"
							+ " FILTER(?member = :red)")) {
				verify(connection, "SELECT ?person", body, rowStrategy, "person", NS + "alice", mismatches);
				verify(connection, "SELECT (COUNT(*) AS ?count)", body, aggregateStrategy, "count", "1", mismatches);
				verify(connection, "SELECT (COUNT(?person) AS ?count)", body, aggregateStrategy, "count", "1",
						mismatches);
				if (body.contains("?nick")) {
					verify(connection, "SELECT ?nick", body, rowStrategy, "nick", "Alice", mismatches);
				}
				if (body.contains("?member")) {
					verify(connection, "SELECT ?member", body, rowStrategy, "member", NS + "red", mismatches);
				}
			}
			assertThat(mismatches).as("raw execution mismatches").isEmpty();
		} finally {
			repository.shutDown();
		}
	}

	private static void verify(SailRepositoryConnection connection, String projection, String body, String strategy,
			String variable, String expected, List<String> mismatches) {
		String query = "PREFIX : <" + NS + "> " + projection + " WHERE { " + body + " }";
		var prepared = connection.prepareTupleQuery(QueryLanguage.SPARQL, query, null);
		if (!"automatic".equals(strategy)) {
			prepared.setForcedLmdbExecutionStrategy(strategy);
		}
		List<String> actual = new ArrayList<>();
		try (var result = prepared.evaluate()) {
			while (result.hasNext()) {
				var value = result.next().getValue(variable);
				actual.add(value == null ? "<unbound>" : value.stringValue());
			}
		}
		if (!actual.equals(List.of(expected))) {
			String mismatch = "strategy=" + strategy + ", expected=" + expected + ", actual=" + actual
					+ ", query=" + query;
			mismatches.add(mismatch);
			System.out.println(mismatch);
			System.out.println("Follow-up optimized explanation:\n" + prepared.explain(Explanation.Level.Optimized));
			System.out.println("Follow-up telemetry explanation:\n" + prepared.explain(Explanation.Level.Telemetry));
		}
	}

	private static void addDataset(SailRepositoryConnection connection) {
		for (String person : List.of("alice", "bob", "carol", "dave")) {
			connection.add(Values.iri(NS + person), RDF.TYPE, Values.iri(NS + "Person"));
		}
		connection.add(Values.iri(NS + "gina"), RDF.TYPE, Values.iri(NS + "Guest"));
		connection.add(Values.iri(NS + "visitor"), RDF.TYPE, Values.iri(NS + "Visitor"));
		for (String[] triple : List.of(
				new String[] { "alice", "knows", "bob" }, new String[] { "alice", "knows", "carol" },
				new String[] { "bob", "knows", "dave" }, new String[] { "carol", "knows", "dave" },
				new String[] { "gina", "knows", "guest-link" }, new String[] { "bob", "friend", "erin" },
				new String[] { "carol", "friend", "fox" }, new String[] { "visitor", "friend", "visitor-link" })) {
			connection.add(Values.iri(NS + triple[0]), Values.iri(NS + triple[1]), Values.iri(NS + triple[2]));
		}
		connection.add(Values.iri(NS + "alice"), Values.iri(NS + "nick"), Values.literal("Alice"));
		connection.add(Values.iri(NS + "bob"), Values.iri(NS + "nick"), Values.literal("Bob"));
		connection.add(Values.iri(NS + "alice"), Values.iri(NS + "status"), Values.iri(NS + "active"));
		connection.add(Values.iri(NS + "bob"), Values.iri(NS + "blocked"), Values.iri(NS + "carol"));
		connection.add(Values.iri(NS + "carol"), Values.iri(NS + "status"), Values.iri(NS + "inactive"));
		connection.add(Values.iri(NS + "alice"), Values.iri(NS + "member"), Values.iri(NS + "red"),
				Values.iri(NS + "graph-one"));
		connection.add(Values.iri(NS + "bob"), Values.iri(NS + "member"), Values.iri(NS + "blue"),
				Values.iri(NS + "graph-one"));
		connection.add(Values.iri(NS + "carol"), Values.iri(NS + "member"), Values.iri(NS + "red"),
				Values.iri(NS + "graph-two"));
	}
}
